        ["本地模式只连接本机地址，例如 http://127.0.0.1:11434/v1。"] = ("Local mode requires a loopback address such as http://127.0.0.1:11434/v1.", "ローカルモードには http://127.0.0.1:11434/v1 などのループバックアドレスを指定してください。", "로컬 모드에는 http://127.0.0.1:11434/v1 같은 루프백 주소를 사용하세요."),
        ["远程 API 需要使用 HTTPS 地址。"] = ("Remote APIs require an HTTPS URL.", "リモート API には HTTPS URL が必要です。", "원격 API에는 HTTPS URL이 필요합니다."),
        ["请输入服务提供的准确模型 ID。"] = ("Enter the exact model ID provided by your service.", "サービスが指定する正確なモデル ID を入力してください。", "서비스에서 제공하는 정확한 모델 ID를 입력하세요."),
        ["API 密钥包含无效字符。"] = ("The API key contains invalid characters.", "API キーに無効な文字が含まれています。", "API 키에 잘못된 문자가 포함되어 있습니다."),
        ["请填写此远程 API 地址的密钥。"] = ("Enter the key for this remote API endpoint.", "このリモート API エンドポイントのキーを入力してください。", "이 원격 API 엔드포인트의 키를 입력하세요."),
        ["无法读取模型设置。请检查本机设置文件。"] = ("Couldn't read model settings. Check the local settings file.", "モデル設定を読み込めませんでした。ローカル設定ファイルを確認してください。", "모델 설정을 읽지 못했습니다. 로컬 설정 파일을 확인하세요."),
        ["无法保存本机模型设置。"] = ("Couldn't save model settings on this computer.", "この PC にモデル設定を保存できませんでした。", "이 컴퓨터에 모델 설정을 저장하지 못했습니다."),
        ["模型回复超时，请重试。"] = ("The model timed out. Try again.", "モデルの応答がタイムアウトしました。もう一度お試しください。", "모델 응답 시간이 초과되었습니다. 다시 시도해 주세요."),
        ["无法连接模型服务。请检查地址、服务状态和网络。"] = ("Couldn't connect to the model service. Check the URL, service status, and network.", "モデルサービスに接続できませんでした。URL、サービスの稼働状況、ネットワークを確認してください。", "모델 서비스에 연결할 수 없습니다. URL, 서비스 상태, 네트워크를 확인하세요."),
        ["读取模型回复时连接中断，请重试。"] = ("The connection dropped while reading the model reply. Try again.", "モデルの応答を読み取る途中で接続が切れました。もう一度お試しください。", "모델 응답을 읽는 중 연결이 끊겼습니다. 다시 시도해 주세요."),
        ["模型服务返回内容过长，本次未保存。"] = ("The model response was too long to save.", "モデルの応答が長すぎるため保存できませんでした。", "모델 응답이 너무 길어 저장하지 못했습니다."),
        ["模型服务未返回有效的聊天回复，本次未保存。"] = ("The model service returned an invalid chat reply, which was discarded.", "モデルサービスから有効な会話の応答が得られなかったため、保存しませんでした。", "모델 서비스에서 유효한 대화 응답을 받지 못해 저장하지 않았습니다."),
        ["模型服务拒绝了认证。请检查 API 密钥和模型权限。"] = ("The service rejected authentication. Check your API key and model permissions.", "認証が拒否されました。API キーとモデルの利用権限を確認してください。", "서비스에서 인증을 거부했습니다. API 키와 모델 권한을 확인하세요."),
        ["模型服务返回用量或余额不足。请检查服务账户。"] = ("The provider reported a usage or balance issue. Check your service account.", "利用枠または残高が不足しています。サービスのアカウントを確認してください。", "제공업체에서 사용량 한도 또는 잔액 부족을 알렸습니다. 서비스 계정을 확인하세요."),
        ["未找到聊天接口或模型。请检查 API 地址与模型 ID。"] = ("Chat endpoint or model unavailable. Check the API URL and model ID.", "チャットのエンドポイントまたはモデルが見つかりません。API の URL とモデル ID を確認してください。", "대화 엔드포인트 또는 모델을 찾을 수 없습니다. API URL과 모델 ID를 확인하세요."),
        ["此地址不接收聊天请求。请填写 API 服务地址。"] = ("This URL doesn't accept chat requests. Enter the API service URL.", "この URL はチャットリクエストを受け付けません。API サービスの URL を入力してください。", "이 URL은 대화 요청을 받지 않습니다. API 서비스 URL을 입력하세요."),
        ["模型服务不接受当前请求。请核对模型 ID 与 JSON 模式支持。"] = ("The service rejected this request. Check the model ID and JSON mode support.", "サービスがこのリクエストを拒否しました。モデル ID と JSON モードへの対応を確認してください。", "서비스가 요청을 거부했습니다. 모델 ID와 JSON 모드 지원 여부를 확인하세요."),
        ["模型服务达到请求或用量限制，请稍后重试。"] = ("The service reached a request or usage limit. Try again later.", "リクエスト数または使用量の上限に達しました。時間をおいて再度お試しください。", "서비스의 요청 또는 사용량 한도에 도달했습니다. 잠시 후 다시 시도해 주세요."),
        ["模型服务暂时不可用（HTTP {0}）。"] = ("The model service is temporarily unavailable (HTTP {0}).", "モデルサービスが一時的に利用できません（HTTP {0}）。", "모델 서비스를 일시적으로 사용할 수 없습니다(HTTP {0})."),
        ["模型连接未成功（HTTP {0}）。请检查 API 地址。"] = ("The model connection failed (HTTP {0}). Check the API URL.", "モデルへの接続に失敗しました（HTTP {0}）。API の URL を確認してください。", "모델 연결에 실패했습니다(HTTP {0}). API URL을 확인하세요."),
        ["本机 API 密钥无法读取，请重新输入。"] = ("Couldn't read the saved API key. Enter it again.", "保存済みの API キーを読み込めませんでした。入力し直してください。", "저장된 API 키를 읽지 못했습니다. 다시 입력하세요."),
        ["当前系统无法保护 API 密钥。"] = ("This system cannot protect the API key.", "このシステムでは API キーを保護できません。", "이 시스템에서는 API 키를 보호할 수 없습니다."),
        ["Windows 无法保护此 API 密钥。"] = ("Windows couldn't protect this API key.", "Windows がこの API キーを保護できませんでした。", "Windows에서 이 API 키를 보호하지 못했습니다."),
        ["Codex 未能启动。"] = ("Codex couldn't start.", "Codex を起動できませんでした。", "Codex를 시작하지 못했습니다."),
        ["无法启动本机 Codex。请检查 Codex 是否可从 Windows 正常运行。"] = ("Couldn't start local Codex. Check that Codex runs normally on Windows.", "この PC の Codex を起動できませんでした。Windows で通常どおり起動できるか確認してください。", "로컬 Codex를 시작하지 못했습니다. Windows에서 Codex가 정상 실행되는지 확인하세요."),
        ["Codex 回复超时，请再试一次。"] = ("Codex timed out. Try again.", "Codex の応答がタイムアウトしました。もう一度お試しください。", "Codex 응답 시간이 초과되었습니다. 다시 시도해 주세요."),
        ["无法和本机 Codex 通信。"] = ("Couldn't communicate with local Codex.", "この PC の Codex と通信できませんでした。", "로컬 Codex와 통신하지 못했습니다."),
        ["本机 Codex 登录不可用。请在 Codex 里登录后再试。"] = ("Codex sign-in is unavailable. Sign in through Codex and try again.", "Codex のログインを確認できませんでした。Codex でログインしてからお試しください。", "Codex 로그인 상태를 확인할 수 없습니다. Codex에 로그인한 뒤 다시 시도해 주세요."),
        ["Codex 暂时达到用量上限，请稍后再试。"] = ("Codex reached its usage limit. Try again later.", "Codex の利用上限に達しました。時間をおいて再度お試しください。", "Codex 사용량 한도에 도달했습니다. 잠시 후 다시 시도해 주세요."),
        ["本机 Codex 未能完成本次对话。请查看 Codex 的登录、网络和版本状态。"] = ("Local Codex couldn't complete this conversation. Check your sign-in, network, and Codex version.", "この PC の Codex が会話を完了できませんでした。ログイン、ネットワーク、Codex のバージョンを確認してください。", "로컬 Codex가 대화를 완료하지 못했습니다. 로그인, 네트워크, Codex 버전을 확인하세요."),
        ["Codex 返回格式无法读取，本次未保存。"] = ("The Codex reply couldn't be read and was discarded.", "Codex の応答形式を読み取れなかったため、保存しませんでした。", "Codex 응답 형식을 읽지 못해 저장하지 않았습니다."),
        ["Codex 没有返回球员的回复，本次未保存。"] = ("Codex returned no player reply, so the turn was discarded.", "Codex が選手の返信を返さなかったため、この会話は保存しませんでした。", "Codex가 선수 응답을 반환하지 않아 이번 대화를 저장하지 않았습니다."),
        ["未找到本机 Codex CLI。请检查 Codex Desktop 是否已安装，或 codex.exe 是否在 PATH。"] = ("Couldn't find the local Codex CLI. Check your Codex Desktop installation or whether codex.exe is on PATH.", "この PC で Codex CLI が見つかりませんでした。Codex Desktop のインストール、または codex.exe の PATH を確認してください。", "로컬 Codex CLI를 찾을 수 없습니다. Codex Desktop이 설치되어 있는지 또는 codex.exe가 PATH에 있는지 확인하세요.")
    };
}
